public class Solution {
    public int[][] permute(int[] A) {
        List<int[]> result = new ArrayList<>();
        backtrack(A, 0, result);
        int[][] ans = new int[result.size()][A.length];
        for (int i = 0; i < result.size(); i++) ans[i] = result.get(i);
        return ans;
    }

    private void backtrack(int[] A, int start, List<int[]> result) {
        if (start == A.length) {
            result.add(A.clone());
            return;
        }
        for (int i = start; i < A.length; i++) {
            swap(A, start, i);
            backtrack(A, start + 1, result);
            swap(A, start, i);
        }
    }

    private void swap(int[] A, int i, int j) {
        int t = A[i]; A[i] = A[j]; A[j] = t;
    }
}

