public class Solution {
    public String[] generateParenthesis(int A) {
        List<String> res = new ArrayList<>();
        backTracking(A, "", 0, 0, res);
        String[] st = new String[res.size()];
        int index =0;
        for(String x : res){
            st[index] = x;
            index++;
        }
        return st;
    }

    public List<String> backTracking(int n, String currentPattern, int openParanthesisCount, int closedParanthesisCount, List<String> result){
        if(openParanthesisCount == n && closedParanthesisCount == n){
            result.add(currentPattern);
            return result;
        }

        if(openParanthesisCount < n){
            backTracking(n, currentPattern + "(", openParanthesisCount+1, closedParanthesisCount, result);
        }

        if(closedParanthesisCount < openParanthesisCount){
            backTracking(n, currentPattern + ")", openParanthesisCount, closedParanthesisCount+1, result);
        }
        return result;
    }
}

class Solution {
    public ArrayList<ArrayList<Integer>> subsets(ArrayList<Integer> A) {
        ArrayList<ArrayList<Integer>> res = new ArrayList<>();
        dfs(A.size(), A, 0, new ArrayList<Integer>(), res);
        return res;
    }

    private ArrayList<ArrayList<Integer>> dfs(int N, ArrayList<Integer> nums, int index, ArrayList<Integer> currentList, ArrayList<ArrayList<Integer>> all){
        if(index >= N){
            all.add(new ArrayList<>(currentList)); // VERY IMPORTANT
            return all;
        }

        currentList.add(nums.get(index));
        dfs(N, nums, index+1, currentList, all);
        currentList.remove(Integer.valueOf(nums.get(index)));
        dfs(N, nums, index+1, currentList, all);

        return all;
    }
}

public class Solution {
    public String[] letterCombinations(String A) {
        String[] map = {"0", "1", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
        List<String> res = new ArrayList<>();
        StringBuilder cur = new StringBuilder();
        solve(A, 0, map, cur, res);
        return res.toArray(new String[0]);
    }
    private void solve(String A, int idx, String[] map, StringBuilder cur, List<String> res) {
        if (idx == A.length()) {
            res.add(cur.toString());
            return;
        }
        String letters = map[A.charAt(idx) - '0'];
        for (int i = 0; i < letters.length(); i++) {
            cur.append(letters.charAt(i));
            solve(A, idx + 1, map, cur, res);
            cur.deleteCharAt(cur.length() - 1);
        }
    }
}

public class Solution {
    public int solve(int A, int B) {
        if (A == 1) return 0;
        int parent = solve(A - 1, B / 2);
        if (B % 2 == 0) return parent;
        else return 1 - parent;
    }
}

