public class Solution {
    public int[][] WaysToClimb(int A) {
        List<List<Integer>> res = new ArrayList<>();
        solve(A, new ArrayList<>(), res);
        int[][] ans = new int[res.size()][];
        for (int i = 0; i < res.size(); i++) {
            List<Integer> path = res.get(i);
            ans[i] = new int[path.size()];
            for (int j = 0; j < path.size(); j++) ans[i][j] = path.get(j);
        }
        return ans;
    }
    private void solve(int rem, List<Integer> cur, List<List<Integer>> res) {
        if (rem == 0) {
            res.add(new ArrayList<>(cur));
            return;
        }
        if (rem >= 1) {
            cur.add(1);
            solve(rem - 1, cur, res);
            cur.remove(cur.size() - 1);
        }
        if (rem >= 2) {
            cur.add(2);
            solve(rem - 2, cur, res);
            cur.remove(cur.size() - 1);
        }
    }
}

