public class Solution {
    public String[] PrintAllPaths(int A, int B) {
        List<String> res = new ArrayList<>();
        solve(0, 0, A, B, new StringBuilder(), res);
        return res.toArray(new String[0]);
    }
    private void solve(int r, int c, int A, int B, StringBuilder path, List<String> res) {
        if (r == A - 1 && c == B - 1) {
            res.add(path.toString());
            return;
        }
        if (r < A - 1) {
            path.append('D');
            solve(r + 1, c, A, B, path, res);
            path.deleteCharAt(path.length() - 1);
        }
        if (c < B - 1) {
            path.append('R');
            solve(r, c + 1, A, B, path, res);
            path.deleteCharAt(path.length() - 1);
        }
    }
}

