public class Solution {
    public int SubsetSum(int[] A, int B) {
        return solve(A, 0, B) ? 1 : 0;
    }
    private boolean solve(int[] A, int idx, long target) {
        if (idx == A.length) return target == 0;
        if (solve(A, idx + 1, target - A[idx])) return true;
        if (solve(A, idx + 1, target)) return true;
        return false;
    }
}
